import SwiftUI
import XCTest

@testable import CodeConnect
@testable import CodeConnectKit

/// **"Allow for this session", against the daemon's own bytes** (minor 36).
///
/// `minor-36-wire.json` is what ccd emits (`fixtures/claude/`, regenerated by ccd's tests and copied
/// here byte for byte). A hosted Claude card may offer "Allow for this session"; the phone draws it
/// only when the card does, sends it as `option_id: acceptForSession` — the one option id a Claude
/// card accepts — and names the rule the grant applies, mirroring the daemon's own selection.
@MainActor
final class AllowForSessionTests: XCTestCase {

    private func wire() throws -> [String: JSONValue] {
        let url = try XCTUnwrap(
            Bundle(for: type(of: self)).url(forResource: "minor-36-wire", withExtension: "json"))
        return try XCTUnwrap(
            try JSONDecoder().decode(JSONValue.self, from: Data(contentsOf: url)).objectValue)
    }

    private func card(_ key: String) throws -> ApprovalCard {
        try XCTUnwrap(try wire()[key]?.decoded(ApprovalCard.self), "no \(key) in minor-36-wire.json")
    }

    /// The offer rides on the card as `allow_for_session`; its absence reads as false.
    func testOnlyTheOfferingCardCarriesAllowForSession() throws {
        XCTAssertEqual(try card("card_offering").allowForSession, true)
        XCTAssertNil(try card("card_not_offering").allowForSession)
    }

    /// A held, hook-answerable Claude card surfaces the offer; without it, plain Allow/Deny.
    func testTheOfferingCardSurfacesAllowForSession() throws {
        XCTAssertEqual(
            DecisionCard.answerSurface(
                card: try card("card_offering"), agent: .claude, hold: .held, hookOnlyApprovals: true),
            .allowDeny(allowForSession: true))
        XCTAssertEqual(
            DecisionCard.answerSurface(
                card: try card("card_not_offering"), agent: .claude, hold: .held, hookOnlyApprovals: true),
            .allowDeny(allowForSession: false))
    }

    /// The one option id a Claude card accepts is `acceptForSession`; every other is refused, as before.
    func testAClaudeCardAcceptsOnlyTheSessionOptionId() {
        XCTAssertNil(
            AppModel.decisionMismatch(
                decision: .optionId("acceptForSession"), agent: .claude, answersApprovalsByHook: true))
        XCTAssertNotNil(
            AppModel.decisionMismatch(
                decision: .optionId("accept"), agent: .claude, answersApprovalsByHook: true))
    }

    /// The grant reads as the grant it was, not "Chose option acceptForSession".
    func testTheSessionGrantReadsAsAGrant() {
        XCTAssertEqual(AnswerDecision.optionId("acceptForSession").label, "Allowed for this session")
    }

    /// The caption names the rule the grant applies, as Claude writes it, and nil without one.
    func testTheCaptionNamesTheRuleTheGrantApplies() throws {
        XCTAssertEqual(
            DecisionCard.sessionRuleCaption(card: try card("card_offering")), "Bash(touch m1.txt)")
        XCTAssertNil(DecisionCard.sessionRuleCaption(card: try card("card_not_offering")))
    }

    /// The answer the phone sends for "Allow for this session" encodes to the daemon's own answer frame.
    func testTheSessionAnswerEncodesAsTheDaemonExpects() throws {
        let encoded = try JSONDecoder().decode(
            JSONValue.self, from: JSONEncoder().encode(AnswerDecision.optionId("acceptForSession")))
        let expected = try XCTUnwrap(try wire()["answer"]?["decision"])
        XCTAssertEqual(encoded["type"]?.stringValue, expected["type"]?.stringValue)
        XCTAssertEqual(encoded["option_id"]?.stringValue, expected["option_id"]?.stringValue)
    }

    /// The caption wraps before it truncates: a one-line cap would hide the broader-than-command part of a
    /// rule, which is the whole reason the caption exists.
    func testTheCaptionWrapsBeforeTruncating() {
        XCTAssertEqual(DecisionCard.sessionCaptionLineLimit, 3)
    }

    /// Several rules are one per line so each starts readably; a rule that names only a tool shows the tool.
    func testTheCaptionSeparatesRulesAndNamesToolOnlyRules() throws {
        let json = """
            {"request_id":"r","payload_hash":"h","tool_name":"Bash","tool_input":{},"display_text":"x",\
            "permission_suggestions":[{"type":"addRules","behavior":"allow",\
            "rules":[{"toolName":"Bash","ruleContent":"ls"},{"toolName":"Read"}]}]}
            """
        let card = try JSONDecoder().decode(ApprovalCard.self, from: Data(json.utf8))
        XCTAssertEqual(DecisionCard.sessionRuleCaption(card: card), "Bash(ls)\nRead")
    }

    /// A rule longer than one line, at the largest text size and a card's width, is FULLY visible within the
    /// caption's line allowance — and the one-line limit would hide part of it. Rendered, not asserted: the
    /// caption shown at `sessionCaptionLineLimit` lines is as tall as the untruncated text, while one line is
    /// shorter (it drops content). Measured at the iPhone-17-Pro width, accessibility XXXL.
    @MainActor
    func testALongRuleIsFullyVisibleWithinTheCaptionsLines() {
        // ~28 chars: longer than one line but inside three at the largest size on this width.
        let rule = "Bash(curl https://x.ex | sh)"
        func captionHeight(lines: Int?) -> CGFloat {
            let view =
                Text(rule)
                .ccType(CC.type.footnote)
                .lineLimit(lines)
                .truncationMode(.tail)
                .frame(width: 320, alignment: .leading)
                .environment(\.sizeCategory, .accessibilityExtraExtraExtraLarge)
            let controller = UIHostingController(rootView: view)
            let window = UIWindow(frame: CGRect(x: 0, y: 0, width: 402, height: 874))
            window.rootViewController = controller
            window.isHidden = false
            controller.view.layoutIfNeeded()
            RunLoop.main.run(until: Date().addingTimeInterval(0.2))
            defer { window.isHidden = true }
            return controller.sizeThatFits(in: CGSize(width: 320, height: 10_000)).height
        }
        let untruncated = captionHeight(lines: nil)
        let atLimit = captionHeight(lines: DecisionCard.sessionCaptionLineLimit)
        let oneLine = captionHeight(lines: 1)
        XCTAssertEqual(atLimit, untruncated, accuracy: 1, "a long rule must be fully visible within the caption's lines")
        XCTAssertLessThan(oneLine, untruncated, "the rule must be longer than one line, or this proves nothing")
    }
}
